#include "node_base_test_fixture.hpp"
using namespace node_base_test;
namespace {
using M=Memory;
void null_parent_and_membership(){
    {CoreFixture f;put(f.raw.bytes,0x48,0x1234);put(f.raw.bytes,0x50,0x5678);put(f.raw.bytes,0x18,0x101,4);put(f.raw.bytes,0x20,0x9876);put(f.raw.bytes,0x28,0x123456);auto expected=f.raw.bytes;reset_value(expected);const auto parent=f.raw.parent_bytes;f.docs.child_hook=[&](auto p){check(p==M::node&&word(f.raw.bytes,0)==node_table,"base table publication precedes same-node child deletion");};f.destroy();check(f.raw.bytes==expected&&f.raw.parent_bytes==parent&&f.docs.children==std::vector<std::uintptr_t>{M::node}&&f.docs.entered_frees.empty()&&!f.docs.other_calls,"null parent preserves nonempty own sibling links and skips free without bit200");}
    for(bool previous:{false,true})for(bool next:{false,true})for(bool head:{false,true})for(bool tail:{false,true}){
        CoreFixture f;put(f.raw.bytes,0x10,M::parent);put(f.raw.bytes,0x48,previous?M::previous:0);put(f.raw.bytes,0x50,next?M::next:0);put(f.raw.parent_bytes,0x38,head?M::node:0xdead);put(f.raw.parent_bytes,0x40,tail?M::node:0xbeef);
        auto node=f.raw.bytes;auto parent=f.raw.parent_bytes;auto prev=f.raw.previous_bytes;auto following=f.raw.next_bytes;reset_value(node);put(node,0x10,0);put(node,0x48,0);put(node,0x50,0);if(head)put(parent,0x38,next?M::next:0);if(tail)put(parent,0x40,previous?M::previous:0);if(previous)put(prev,0x50,next?M::next:0);if(next)put(following,0x48,previous?M::previous:0);f.destroy();
        check(f.raw.bytes==node&&f.raw.parent_bytes==parent&&f.raw.previous_bytes==prev&&f.raw.next_bytes==following,"all head/tail/previous/next combinations preserve exact membership-mismatch updates and own unlink fields");check(f.docs.children==std::vector<std::uintptr_t>{M::node}&&f.docs.entered_frees.empty()&&!f.docs.other_calls,"own unlink adds no probe/destructor/pool/registry providers");
    }
}
void flags_and_child_effects(){
    for(bool linked:{false,true})for(std::uintptr_t p:{std::uintptr_t{0},std::uintptr_t{0x77112233}}){CoreFixture f;if(linked)f.raw.linked();put(f.raw.bytes,0x18,0xa0000201,4);put(f.raw.bytes,0x1c,0xdeadbeef,4);put(f.raw.bytes,0x20,p);put(f.raw.bytes,0x28,99);f.docs.before_free=[&](auto arg){check(arg==p&&word(f.raw.bytes,0)==node_table&&(!linked||(!word(f.raw.bytes,0x10)&&!word(f.raw.bytes,0x48)&&!word(f.raw.bytes,0x50))),"flagged free follows child deletion and completed optional unlink, including null storage pointer");};f.docs.after_free=[&](auto){put(f.raw.bytes,0x18,0xffffffff,4);put(f.raw.bytes,0x20,0xaaaa);put(f.raw.bytes,0x28,0xbbbb);};f.destroy();check(f.docs.completed_frees==std::vector<std::uintptr_t>{p}&&!word(f.raw.bytes,0x18,4)&&word(f.raw.bytes,0x1c,4)==0xdeadbeef&&!word(f.raw.bytes,0x20)&&!word(f.raw.bytes,0x28),"post-free final fields reset as DWORD/QWORD/QWORD while padding1c remains unchanged");}
    {CoreFixture f;f.docs.child_hook=[&](auto){f.raw.linked();put(f.raw.bytes,0x18,0x200,4);put(f.raw.bytes,0x20,0x8899);};f.destroy();check(f.docs.completed_frees==std::vector<std::uintptr_t>{0x8899}&&word(f.raw.parent_bytes,0x38)==M::next&&word(f.raw.parent_bytes,0x40)==M::previous&&!word(f.raw.bytes,0x10),"parent/siblings/flags/storage are all read live after child provider mutation");}
    {CoreFixture f;auto expected=f.raw.bytes;put(expected,0,node_table);f.docs.child_hook=[](auto){throw Failure{77};};failure([&]{f.destroy();});check(f.raw.bytes==expected&&f.docs.children.size()==1&&f.docs.entered_frees.empty(),"child deletion failure retains base-table publication and prevents all later reads/stores/free");}
}
void alias_order(){
    {CoreFixture f;f.raw.linked();f.raw.regions={{M::node,f.raw.bytes},{M::parent,std::span(f.raw.parent_bytes).first(0x40)},{M::parent+0x40,std::span(f.raw.parent_bytes).subspan(0x38,8)},{M::parent+0x48,std::span(f.raw.parent_bytes).subspan(0x48)},{M::previous,f.raw.previous_bytes},{M::next,f.raw.next_bytes}};f.raw.memory.regions=f.raw.regions;f.destroy();check(f.raw.get(M::parent+0x38)==M::next&&f.raw.get(M::parent+0x40)==M::next,"tail is loaded after head store changes its aliased backing, so stale original tail match is not reused");}
    {CoreFixture f;f.raw.linked();f.raw.omitted={{M::previous+0x50,8}};f.raw.extras.push_back({M::previous+0x50,std::span(f.raw.bytes).subspan(0x48,8)});f.raw.refresh();f.destroy();check(word(f.raw.next_bytes,0x48)==M::next&&!word(f.raw.bytes,0x48),"next sibling update reloads previous after prior neighbor store aliases own previous field");}
    {CoreFixture f;f.raw.linked();std::array<std::uint8_t,0x80> shadow{};const std::uintptr_t changed_next=M::next+(std::uint64_t{M::next}<<32);f.raw.omitted={{M::previous+0x50,8}};f.raw.extras.push_back({M::previous+0x50,std::span(f.raw.bytes).subspan(0x54,8)});f.raw.extras.push_back({changed_next,shadow});f.raw.refresh();const auto old_next=f.raw.next_bytes;f.destroy();check(word(shadow,0x48)==M::previous&&f.raw.next_bytes==old_next,"next is reloaded after previous-neighbor store changes high bytes of own next pointer");}
}
void bounded_and_free_failures(){
    {CoreFixture f;const auto expected=f.raw.bytes;f.raw.omitted={{M::node,8}};f.raw.refresh();unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&f.docs.children.empty(),"missing base-table mapping prevents child call");}
    for(unsigned at:{0x10U,0x18U,0x20U,0x28U}){CoreFixture f;put(f.raw.bytes,0x20,0x1234);put(f.raw.bytes,0x28,0x5678);put(f.raw.bytes,0x18,0,4);auto expected=f.raw.bytes;put(expected,0,node_table);if(at==0x20||at==0x28)put(expected,0x18,0,4);if(at==0x28)put(expected,0x20,0);f.raw.omitted={{M::node+at,at==0x18?4U:8U}};f.raw.refresh();unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&f.docs.children.size()==1&&f.docs.entered_frees.empty(),"missing parent/flags/reset cell preserves exact base/child/final-reset prefix");}
    {CoreFixture f;f.raw.linked();auto expected=f.raw.bytes;put(expected,0,node_table);f.raw.omitted={{M::parent+0x40,8}};f.raw.refresh();unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&word(f.raw.parent_bytes,0x38)==M::next,"missing live tail mapping preserves preceding parent head update");}
    {CoreFixture f;f.raw.linked();auto expected=f.raw.bytes;put(expected,0,node_table);f.raw.omitted={{M::next+0x48,8}};f.raw.refresh();unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&word(f.raw.parent_bytes,0x38)==M::next&&word(f.raw.parent_bytes,0x40)==M::previous&&word(f.raw.previous_bytes,0x50)==M::next,"missing next-neighbor slot retains head/tail/previous-neighbor writes before own zeroing");}
    {CoreFixture f;f.raw.linked();f.raw.omitted={{M::node+0x48,8}};f.raw.refresh();auto expected=f.raw.bytes;put(expected,0,node_table);unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&word(f.raw.parent_bytes,0x38)==M::next,"missing previous field fails during tail update after committed head update");}
    {CoreFixture f;put(f.raw.bytes,0x18,0x200,4);f.raw.omitted={{M::node+0x20,8}};f.raw.refresh();auto expected=f.raw.bytes;put(expected,0,node_table);unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&f.docs.entered_frees.empty(),"flagged missing storage pointer fails before free or field resets");}
    {CoreFixture f;f.raw.extras.push_back({M::node+0x18,std::span(f.raw.parent_bytes).first(4)});f.raw.refresh();auto expected=f.raw.bytes;put(expected,0,node_table);unsupported([&]{f.destroy();});check(f.raw.bytes==expected,"ambiguous flag mapping fails after base/child prefix without resets");}
    for(bool after:{false,true}){CoreFixture f;f.raw.linked();put(f.raw.bytes,0x18,0x200,4);put(f.raw.bytes,0x20,0x9999);put(f.raw.bytes,0x28,123);auto expected=f.raw.bytes;put(expected,0,node_table);put(expected,0x10,0);put(expected,0x48,0);put(expected,0x50,0);const auto hook=[](auto){throw Failure{77};};if(after)f.docs.after_free=hook;else f.docs.before_free=hook;failure([&]{f.destroy();});check(f.raw.bytes==expected&&f.docs.completed_frees.size()==(after?1U:0U)&&word(f.raw.previous_bytes,0x50)==M::next&&word(f.raw.next_bytes,0x48)==M::previous,"free failure retains full unlink/base publication and prevents all three final field resets");}
    for(unsigned stop:{0x18U,0x20U,0x28U}){CoreFixture f;put(f.raw.bytes,0x18,0x200,4);put(f.raw.bytes,0x20,0x9999);put(f.raw.bytes,0x28,123);auto expected=f.raw.bytes;put(expected,0,node_table);if(stop>0x18)put(expected,0x18,0,4);if(stop>0x20)put(expected,0x20,0);f.docs.after_free=[&](auto){f.raw.omitted={{M::node+stop,stop==0x18?4U:8U}};f.raw.refresh();};unsupported([&]{f.destroy();});check(f.raw.bytes==expected&&f.docs.completed_frees==std::vector<std::uintptr_t>{0x9999},"post-free missing final field retains preceding DWORD/QWORD reset stores");}
}
}
int main(){try{null_parent_and_membership();flags_and_child_effects();alias_order();bounded_and_free_failures();std::cout<<"PASS: "<<checks<<" node-base core checks; null/non-null parent and memberships,live child/free effects,neighbor aliases,flagged storage widths and committed failure prefixes; child/free lower providers supplied\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected failure after "<<checks<<" checks\n";return 1;}}
